/** What the hero is about: the whole title, one season, or one episode. */
function subject({
  item,
  season,
  episode
}) {
  if (episode) {
    return {
      poster: season.poster,
      backdrop: episode.still,
      meta: [`Season ${season.number}, Episode ${episode.n}`, episode.date, episode.runtime],
      score: ring({
        value: episode.score,
        label: ['TMDB', m("br", null), 'episode score']
      }),
      credits: [['Directed by', episode.directors.join(', ')], ['Written by', episode.writers.join(', ')], ['Network', item.credits.find(([k]) => k === 'Network')?.[1]]],
      overview: episode.overview,
      people: ['Guest stars', episode.guests],
      url: episodeUrl(item, season, episode)
    };
  }
  if (season) {
    return {
      poster: season.poster,
      backdrop: item.backdrop,
      meta: [`Season ${season.number}`, season.year, `${season.episodes.length} episodes`, item.genres.join(', ')],
      score: ring({
        value: season.score,
        label: ['TMDB', m("br", null), 'season score']
      }),
      credits: item.credits,
      overview: season.overview,
      people: ['Cast', item.cast],
      url: `${item.url}/season/${season.number}`
    };
  }
  return {
    poster: item.poster,
    backdrop: item.backdrop,
    meta: [...item.meta, item.genres.join(', ')],
    score: item.type === 'game' ? [ring({
      value: item.critic,
      label: ['Critic', m("br", null), 'rating'],
      kind: 'critic'
    }), ring({
      value: item.users,
      label: ['IGDB member', m("br", null), 'rating'],
      kind: 'users'
    }), m("ul", {
      className: "MarqueeHero-chips"
    }, item.platforms.map(p => m("li", null, p)))] : [ring({
      value: item.score,
      label: ['TMDB', m("br", null), 'user score']
    }), item.tagline && m("p", {
      className: "MarqueeHero-tagline"
    }, item.tagline)],
    credits: item.credits,
    overview: item.overview,
    people: item.cast && ['Cast', item.cast],
    url: item.url
  };
}

