import Component from 'flarum/common/Component';
import { label, pad } from '../fixtures';

/**
 * For a TV show: narrow the discussion to one season, or one episode of it.
 * Changing either rewrites the title to match.
 */
export default class ScopePicker extends Component {
  view() {
    const fields = this.attrs.composer.fields;
    const {
      item,
      season,
      episode
    } = fields.marquee;
    const set = (s, e) => {
      fields.marquee = {
        item,
        season: s,
        episode: e
      };
      fields.title(label(item, s, e));
    };
    return m("span", {
      className: "Marquee-scope"
    }, m("select", {
      className: "FormControl",
      "aria-label": "Season",
      value: season ? String(season.number) : '',
      onchange: ev => set(item.seasons.find(s => String(s.number) === ev.target.value), null)
    }, m("option", {
      value: ""
    }, "Whole show"), item.seasons.map(s => m("option", {
      value: String(s.number)
    }, "Season ", s.number, " (", s.year, ")"))), season && m("select", {
      className: "FormControl",
      "aria-label": "Episode",
      value: episode ? String(episode.n) : '',
      onchange: ev => set(season, season.episodes.find(e => String(e.n) === ev.target.value) || null)
    }, m("option", {
      value: ""
    }, "Whole season"), season.episodes.map(e => m("option", {
      value: String(e.n)
    }, "E", pad(e.n), " \xB7 ", e.title))));
  }
}
flarum.reg.add('ernestdefoe-marquee', 'forum/components/ScopePicker', ScopePicker);